// CORRECT — WP 6.4.0+
// Use the consolidated function that handles decoding + loading + fetchpriority
$img_html = '<img src="example.jpg" alt="" />';
$img_html = wp_img_tag_add_loading_optimization_attrs( $img_html, 'custom-context' );
echo $img_html;

// Or let WordPress handle it automatically on the_post_thumbnail(), wp_get_attachment_image(), etc.
