// WRONG — deprecated since WP 6.4.0
if ( ! function_exists( 'wp_img_tag_add_decoding_attr' ) ) {
    return;
}

// Themes/plugins calling the deprecated function
$img_html = '<img src="example.jpg" alt="" />';
$img_html = wp_img_tag_add_decoding_attr( $img_html, 'custom-context' );
