entries.code_example:
// CORRECT — escaping at output boundary
$post_title = get_the_title();
echo '<h4>' . esc_html( $post_title ) . '</h4>';

// CORRECT — URL in href attribute
$permalink = get_permalink();
echo '<a href="' . esc_url( $permalink ) . '">' . esc_html( get_the_title() ) . '</a>';

// CORRECT — URL in src attribute
$image_url = get_the_post_thumbnail_url();
echo '<img alt="" src="' . esc_url( $image_url ) . '" />';

// CORRECT — data attribute (JSON/JS context)
$my_value = sanitize_text_field( $_POST['some_value'] ?? '' );
echo '<div data-value="' . esc_attr( $my_value ) . '"></div>';

// CORRECT — For rich HTML that should allow some tags
$content = get_the_content();
echo wp_kses_post( $content );

entries.bad_pattern:
// WRONG — no escaping; XSS vulnerability
$post_title = get_the_title();
echo '<h4>' . $post_title . '</h4>';

// WRONG — unescaped URL attribute
$permalink = get_permalink();
echo '<a href="' . $permalink . '">' . get_the_title() . '</a>';

// WRONG — unescaped image src
$image_url = get_the_post_thumbnail_url();
echo '<img alt="" src="' . $image_url . '" />';

// WRONG — unescaped JavaScript context
$my_value = $_POST['some_value'];
echo '<div data-value="' . $my_value . '"></div>';

entries.code_example:
// CORRECT — .env is git-ignored and not in repository
// File: .gitignore
.env
.env.local
.env.*.local
/vendor/
/node_modules/

// CORRECT — .env.example exists (template, no real secrets)
// File: .env.example (tracked; used by developers to create .env locally)
DB_HOST=localhost
DB_USER=wp_user
DB_PASSWORD=CHANGE_ME_IN_LOCAL_ENV
API_KEY=your-api-key-here

// CORRECT — Load .env at runtime from gitignored .env file
// File: wp-config.php or config.php
require_once __DIR__ . '/vendor/autoload.php';
$dotenv = Dotenv\Dotenv::createImmutable( __DIR__ );
$dotenv->load();

$db_host = $_ENV['DB_HOST'] ?? 'localhost';
$db_pass = $_ENV['DB_PASSWORD'] ?? '';
$api_key = $_ENV['API_KEY'] ?? '';

// CORRECT — If .env was already committed: remove from history
// $ git rm --cached .env
// $ echo ".env" >> .gitignore
// $ git add .gitignore
// $ git commit -m "Remove tracked .env file with secrets"
// $ git push

entries.bad_pattern:
// WRONG — .env file IS tracked in git (contains real secrets)
// File: .env (committed in git)
DB_HOST=prod.example.com
DB_USER=admin
DB_PASSWORD=SuperSecret123!
API_KEY=sk-live-1234567890abcdef
STRIPE_SECRET=sk_live_...

// WRONG — no .gitignore rule for .env files
// File: .gitignore (missing .env entry)
node_modules/
*.log
// (no .env rule — files get committed)

// WRONG — loading from tracked .env with creds
require_once __DIR__ . '/.env';
$db_pass = $_ENV['DB_PASSWORD'];  // Exposes from history

entries.code_example:
// CORRECT — .gitignore excludes vendor/ but NOT composer.lock
// File: .gitignore
vendor/
node_modules/
.DS_Store
# (no rule for composer.lock — it stays tracked)

// CORRECT — Both files tracked in git
// File: composer.json (tracked)
{
  "name": "my-plugin",
  "require": {
    "vendor/package": "^2.0"
  }
}

// File: composer.lock (tracked — exact versions, reproducible)
{
  "packages": [
    {
      "name": "vendor/package",
      "version": "2.4.3",  // Exact version, not a range
      ...
    }
  ]
}

# Result: deterministic builds
$ composer install
# uses composer.lock; all environments get vendor/package@2.4.3
$ git status
# nothing to commit; lock file is already in git

entries.bad_pattern:
# File: .gitignore (WRONG — excludes the lock file)
vendor/
composer.lock  # <-- WRONG: lock file is gitignored

// File: composer.json (tracked, but lock file missing from git)
{
  "name": "my-plugin",
  "require": {
    "vendor/package": "^2.0"  // Open range; each install gets a different version
  }
}

# Result: random versions installed
$ composer install
$ git status
# composer.lock is NOT in git; every developer's vendor/ may differ

entries.code_example:
// CORRECT — Load secrets from environment variables via .env
// File: .env (local, gitignored)
STRIPE_SECRET_KEY=sk_live_EXAMPLE_not_a_real_key
SENDGRID_API_KEY=SG.EXAMPLE_not_a_real_key
GITHUB_TOKEN=ghp_EXAMPLE_not_a_real_key
DATABASE_PASSWORD=EXAMPLE_not_a_real_password

// File: wp-config.php or bootstrap (load .env)
require_once __DIR__ . '/vendor/autoload.php';
$dotenv = Dotenv\Dotenv::createImmutable( __DIR__ );
$dotenv->load();

// CORRECT — Read secrets from environment
// File: src/Services/PaymentGateway.php
class PaymentGateway {
    public function chargeCard( $amount ) {
        // Load secret at runtime from environment, never hardcoded
        $stripe_key = $_ENV['STRIPE_SECRET_KEY'] ?? '';
        if ( empty( $stripe_key ) ) {
            throw new \Exception( 'STRIPE_SECRET_KEY not set in environment' );
        }
        $stripe = new \Stripe\StripeClient( $stripe_key );
        return $stripe->charges->create( [
            'amount' => $amount,
            'currency' => 'usd',
        ] );
    }
}

// CORRECT — OAuth token from environment
// File: src/ExternalAPI.php
$oauth_token = $_ENV['GITHUB_TOKEN'] ?? '';
if ( empty( $oauth_token ) ) {
    throw new \Exception( 'GITHUB_TOKEN not set' );
}
$headers = [ 'Authorization' => "Bearer {$oauth_token}" ];
$response = wp_remote_get( 'https://api.github.com/user', compact( 'headers' ) );

entries.bad_pattern:
// WRONG — hardcoded API key in code (accessible to everyone with repo access)
// File: src/Services/PaymentGateway.php
class PaymentGateway {
    private const STRIPE_SECRET = 'sk_live_EXAMPLE_not_a_real_key';

    public function chargeCard( $amount ) {
        $stripe = new \Stripe\StripeClient( self::STRIPE_SECRET );
        return $stripe->charges->create( [
            'amount' => $amount,
            'currency' => 'usd',
        ] );
    }
}

// WRONG — API key in configuration file committed to git
// File: wp-config.php or config/settings.php
define( 'SENDGRID_API_KEY', 'SG.EXAMPLE_not_a_real_key' );
define( 'DATABASE_PASSWORD', 'EXAMPLE_not_a_real_password' );

// WRONG — hardcoded OAuth token in plugin
// File: plugins/my-plugin/src/ExternalAPI.php
$oauth_token = 'ghp_EXAMPLE_not_a_real_key';
$headers = [ 'Authorization' => "Bearer {$oauth_token}" ];
$response = wp_remote_get( 'https://api.github.com/user', compact( 'headers' ) );

// Missing $schema, wrong apiVersion, hard-coded script URL
{
  "name": "my-plugin/My Block",       // spaces / uppercase not allowed in name
  "apiVersion": 1,                     // deprecated; blocks lose inner-blocks support
  "script": "https://cdn.example.com/block.js"  // never use external URLs here
}
